        hitDice: '10d8',
        speed: { walk: 40 },
        scores: { str: 13, dex: 15, con: 13, int: 12, wis: 14, cha: 8 },
        initiative: 'proficient',
        saves: { dex: 'proficient' },
        senses: { darkvision: 60 },
        damageImmunities: [rules.poison],
